hubs.smoke:
$token = Get-HubEnv 'YANDEX_DIRECT_TOKEN'
if (-not $token) { throw 'no token' }
$h = @{ Authorization = 'Bearer ' + $token; 'Accept-Language' = 'ru' }
$b = '{"method":"get","params":{"SelectionCriteria":{},"FieldNames":["Id","Name"]}}'
$r = Invoke-RestMethod -Uri ($base + '/json/v5/campaigns') -Method Post -Headers $h -ContentType 'application/json; charset=utf-8' -Body $b -TimeoutSec 30
if ($r.error) {
    $code = $r.error.error_code
    Write-Output ('API-ERROR: ' + $code + ' ' + $r.error.error_string + ' — ' + $r.error.error_detail)
    if ($code -eq 58) { Write-Output 'STATUS: BLOCKED (access request not approved)'; exit 2 }
    if ($code -eq 53) { Write-Output 'STATUS: FAIL (token rejected)'; exit 1 }
    Write-Output 'STATUS: FAIL (live smoke: API error)'; exit 1
}
"campaigns: $($r.result.Campaigns.Count) host=$base"

$key = Get-HubEnv 'YC_API_KEY'
$folder = Get-HubEnv 'YC_FOLDER_ID'
if (-not $key -or -not $folder) { throw 'no key or folder' }
$h = @{ Authorization = 'Api-key ' + $key }
$b = @{ folderId = $folder; phrase = 'натяжные потолки'; numPhrases = 5 } | ConvertTo-Json -Compress
$r = Invoke-RestMethod -Uri 'https://searchapi.api.cloud.yandex.net/v2/wordstat/topRequests' -Method Post -Headers $h -ContentType 'application/json; charset=utf-8' -Body ([Text.Encoding]::UTF8.GetBytes($b)) -TimeoutSec 30
if ($r.error) { throw ('API error: ' + ($r.error | ConvertTo-Json -Compress)) }
if (-not ($r.PSObject.Properties.Name -contains 'totalCount')) { throw 'no totalCount in response' }
"total: $($r.totalCount)"

$token = Get-HubEnv 'YANDEX_WEBMASTER_TOKEN'
if (-not $token) { throw 'no token' }
$h = @{ Authorization = 'OAuth ' + $token }
$u = Invoke-RestMethod -Uri 'https://api.webmaster.yandex.net/v4/user/' -Headers $h -TimeoutSec 20
$hosts = @((Invoke-RestMethod -Uri ('https://api.webmaster.yandex.net/v4/user/' + $u.user_id + '/hosts/') -Headers $h -TimeoutSec 20).hosts)
if ($hosts.Count -lt 1) { throw 'no hosts for this account' }
$primary = @($hosts | Where-Object { $_.host_id -like 'https:*' })[0]
if (-not $primary) { $primary = $hosts[0] }
$hostId = $primary.host_id
$summary = Invoke-RestMethod -Uri ('https://api.webmaster.yandex.net/v4/user/' + $u.user_id + '/hosts/' + $hostId + '/summary/') -Headers $h -TimeoutSec 20
if ($null -eq $summary.sqi) { throw ('summary has no sqi for ' + $hostId) }
'webmaster user ' + $u.user_id + ' hosts ' + $hosts.Count + ' summary ' + $hostId + ' sqi=' + $summary.sqi + ' pages=' + $summary.searchable_pages_count

$token = Get-HubEnv 'YANDEX_DISK_TOKEN'
if (-not $token) { throw 'no token' }
$h = @{ Authorization = 'OAuth ' + $token; Accept = 'application/json' }
$d = Invoke-RestMethod -Uri 'https://cloud-api.yandex.net/v1/disk/' -Headers $h -TimeoutSec 20
'disk total ' + $d.total_space + ' used ' + $d.used_space

$id = Get-HubEnv 'GOOGLE_OAUTH_CLIENT_ID'
$secret = Get-HubEnv 'GOOGLE_OAUTH_CLIENT_SECRET'
$refresh = Get-HubEnv 'GOOGLE_OAUTH_REFRESH_TOKEN'
if (-not $id -or -not $secret -or -not $refresh) { throw 'no credentials' }
$body = @{ client_id = $id; client_secret = $secret; refresh_token = $refresh; grant_type = 'refresh_token' }
$t = Invoke-RestMethod -Uri 'https://oauth2.googleapis.com/token' -Method Post -ContentType 'application/x-www-form-urlencoded' -Body $body -TimeoutSec 30
$h = @{ Authorization = 'Bearer ' + $t.access_token }
$s = Invoke-RestMethod -Uri 'https://www.googleapis.com/webmasters/v3/sites' -Headers $h -TimeoutSec 30
'sites: ' + $s.siteEntry.Count
